        viewVideo    = findViewById(R.id.viewVideo);
        viewDocument = findViewById(R.id.viewDocument);
        viewQuiz     = findViewById(R.id.viewQuiz);

        ivVideoThumbnail  = findViewById(R.id.ivVideoThumbnail);
        btnVideoPlay      = findViewById(R.id.btnVideoPlay);
        ivPlayPauseIcon   = findViewById(R.id.ivPlayPauseIcon);
        tvVideoDuration   = findViewById(R.id.tvVideoDuration);
        tvVideoTitle      = findViewById(R.id.tvVideoTitle);
        tvVideoChapter    = findViewById(R.id.tvVideoChapter);
        videoProgressBar  = findViewById(R.id.videoProgressBar);

        videoView         = findViewById(R.id.videoView);
        videoOverlay      = findViewById(R.id.ivVideoThumbnail); // Optional, we can just cast it or find dark overlay

        btnVideoPlay.setOnClickListener(v -> toggleVideoPlayback());

        tvDocMeta        = findViewById(R.id.tvDocMeta);
        tvDocumentTitle  = findViewById(R.id.tvDocumentTitle);
        webViewDocument  = findViewById(R.id.webViewDocument);

        tvQuestionCounter = findViewById(R.id.tvQuestionCounter);
        tvQuizTimer       = findViewById(R.id.tvQuizTimer);
        quizProgressBar   = findViewById(R.id.quizProgressBar);
        tvQuestionText    = findViewById(R.id.tvQuestionText);
        rvQuizOptions     = findViewById(R.id.rvQuizOptions);
        layoutQuizFeedback= findViewById(R.id.layoutQuizFeedback);
        ivFeedbackIcon    = findViewById(R.id.ivFeedbackIcon);
        tvFeedbackTitle   = findViewById(R.id.tvFeedbackTitle);
        tvFeedbackDetail  = findViewById(R.id.tvFeedbackDetail);

        rvQuizOptions.setLayoutManager(new LinearLayoutManager(this));
        rvQuizOptions.setNestedScrollingEnabled(false);

        btnPrevLesson   = findViewById(R.id.btnPrevLesson);
        btnPrimaryAction= findViewById(R.id.btnPrimaryAction);

        sheetOverlay = findViewById(R.id.sheetOverlay);
        sheetOverlay.setOnClickListener(v -> collapseBottomSheet());

        tvSheetSubtitle = findViewById(R.id.tvSheetSubtitle);
        tvSheetProgress = findViewById(R.id.tvSheetProgress);
    }

    private void loadLesson(int index) {
        pauseVideo();
        currentIndex = index;
        LessonResponse lesson = lessons.get(index);
        currentLessonId = lesson.getId();

        activeLessonId = lesson.getId();

        tvChapterLabel.setText("Bài học:");
        tvLessonTitle.setText(lesson.getTitle());

        viewVideo.setVisibility(View.GONE);
        viewDocument.setVisibility(View.GONE);
        viewQuiz.setVisibility(View.GONE);

        cancelQuizTimer();

        String typeStr = lesson.getLessonType() != null ? lesson.getLessonType() : "";
        if (typeStr.equalsIgnoreCase("VIDEO")) {
            viewVideo.setVisibility(View.VISIBLE);
            bindVideo(lesson);
        } else if (typeStr.equalsIgnoreCase("DOCUMENT") || typeStr.equalsIgnoreCase("ARTICLE")) {
            viewDocument.setVisibility(View.VISIBLE);
            bindDocument(lesson);
        } else if (typeStr.equalsIgnoreCase("QUIZ")) {
            viewQuiz.setVisibility(View.VISIBLE);
            bindQuiz(lesson);
        } else {
            viewDocument.setVisibility(View.VISIBLE);
            bindDocument(lesson);
        }

        updateBottomBarState(lesson);
        refreshSheetAdapter();
    }

    private void bindVideo(LessonResponse lesson) {
        isVideoPlaying = false;
        currentVideoUrl = null;
        videoView.setVisibility(View.GONE);
        ivVideoThumbnail.setVisibility(View.VISIBLE);

        ivPlayPauseIcon.setImageResource(R.drawable.ic_play);
        videoProgressBar.setProgress(0);
        currentVideoPositionSeconds = 0;

        tvVideoTitle.setText(lesson.getTitle());
        tvVideoChapter.setText("");
        tvVideoDuration.setText(lesson.getDuration() != null ? (lesson.getDuration() / 60) + " phút" : "0 phút");

        ivVideoThumbnail.setImageResource(R.drawable.ic_play_circle);

        courseService.getVideoByLessonId(lesson.getId()).enqueue(new Callback<ApiResponse<VideoLessonResponse>>() {
            @Override
            public void onResponse(Call<ApiResponse<VideoLessonResponse>> call, Response<ApiResponse<VideoLessonResponse>> response) {
                if (response.isSuccessful() && response.body() != null && response.body().getData() != null) {
                    VideoLessonResponse videoData = response.body().getData();
                    currentVideoUrl = videoData.getVideoUrl();
                }
            }
            @Override
            public void onFailure(Call<ApiResponse<VideoLessonResponse>> call, Throwable t) {}
        });
    }

    private void toggleVideoPlayback() {
        if (currentVideoUrl == null) {
            ToastUtil.showCustomToast(this, "Video đang tải hoặc không có sẵn");
            return;
        }

        if (isVideoPlaying) {
            pauseVideo();
        } else {
            playVideo();
        }
    }

    private void playVideo() {
        isVideoPlaying = true;
        ivPlayPauseIcon.setImageResource(R.drawable.ic_pause);
        ivVideoThumbnail.setVisibility(View.GONE);
        videoView.setVisibility(View.VISIBLE);

        if (!videoView.isPlaying()) {
            if (currentVideoPositionSeconds == 0) {
                videoView.setVideoPath(currentVideoUrl);
                android.widget.MediaController mediaController = new android.widget.MediaController(this);
                mediaController.setAnchorView(videoView);
                videoView.setMediaController(mediaController);
                videoView.setOnPreparedListener(mp -> {
                    mp.start();
                    videoProgressBar.setMax(mp.getDuration() / 1000);
                });
                videoView.setOnCompletionListener(mp -> {
                    pauseVideo();
                    completedLessonIds.add(currentLessonId);
                    handlePrimaryAction();
                });
            } else {
                videoView.start();
            }
        }

        if (trackingRunnable == null) {
            trackingRunnable = new Runnable() {
                @Override
                public void run() {
                    currentVideoPositionSeconds += 10;
                    if (videoView.isPlaying()) {
                        videoProgressBar.setProgress(videoView.getCurrentPosition() / 1000);
                        currentVideoPositionSeconds = videoView.getCurrentPosition() / 1000;
                    }

                    TrackingVideoLessonRequest req = new TrackingVideoLessonRequest();
                    req.setVideoLessonId(currentLessonId); // Need video id really, fallback to lesson id
                    req.setCurrentPosition(currentVideoPositionSeconds);

                    learningService.trackVideoProgress(req).enqueue(new Callback<ApiResponse<Object>>() {
                        @Override
                        public void onResponse(Call<ApiResponse<Object>> call, Response<ApiResponse<Object>> response) {}
                        @Override
                        public void onFailure(Call<ApiResponse<Object>> call, Throwable t) {}
                    });

                    trackingHandler.postDelayed(this, 10000);
                }
            };
        }
        trackingHandler.postDelayed(trackingRunnable, 10000);
    }

    private void pauseVideo() {
        isVideoPlaying = false;
        if (ivPlayPauseIcon != null) {
            ivPlayPauseIcon.setImageResource(R.drawable.ic_play);
        }

        if (videoView != null && videoView.isPlaying()) {
            videoView.pause();
        }

        if (trackingHandler != null && trackingRunnable != null) {
            trackingHandler.removeCallbacks(trackingRunnable);
            trackingRunnable = null;
        }
    }

    @SuppressLint("SetJavaScriptEnabled")
    private void bindDocument(LessonResponse lesson) {
        tvDocMeta.setText("Bài đọc • " + (lesson.getDuration() != null ? (lesson.getDuration()/60)+" phút" : ""));
        tvDocumentTitle.setText(lesson.getTitle());

        WebSettings settings = webViewDocument.getSettings();
        settings.setJavaScriptEnabled(false);
        settings.setLoadWithOverviewMode(true);
        settings.setUseWideViewPort(true);
        settings.setSupportZoom(false);
        settings.setBuiltInZoomControls(false);

        webViewDocument.setWebViewClient(new WebViewClient());
        webViewDocument.setScrollBarStyle(WebView.SCROLLBARS_OUTSIDE_OVERLAY);

        courseService.getArticleByLessonId(lesson.getId()).enqueue(new Callback<ApiResponse<ArticleLessonResponse>>() {
            @Override
            public void onResponse(Call<ApiResponse<ArticleLessonResponse>> call, Response<ApiResponse<ArticleLessonResponse>> response) {
                String content = "";
                if (response.isSuccessful() && response.body() != null && response.body().getData() != null) {
                    content = response.body().getData().getContent();
                }
                if (content == null) content = "<p>Nội dung trống</p>";
                String html = buildStyledHtml(content);
                webViewDocument.loadDataWithBaseURL(null, html, "text/html", "UTF-8", null);
            }
            @Override
            public void onFailure(Call<ApiResponse<ArticleLessonResponse>> call, Throwable t) {
                String html = buildStyledHtml("<p>Lỗi kết nối</p>");
                webViewDocument.loadDataWithBaseURL(null, html, "text/html", "UTF-8", null);
            }
        });
    }

    private String buildStyledHtml(String bodyContent) {
        return "<!DOCTYPE html><html><head>"
                + "<meta name='viewport' content='width=device-width, initial-scale=1.0'>"
                + "<style>"
                + "body{font-family:-apple-system,sans-serif;font-size:15px;color:#1E293B;"
                + "line-height:1.7;padding:0;margin:0;background:transparent;}"
                + "h1{font-size:22px;font-weight:800;margin-top:8px;margin-bottom:12px;color:#0F172A;}"
                + "h2{font-size:17px;font-weight:700;margin-top:24px;margin-bottom:8px;color:#1E293B;"
                + "border-left:4px solid #7C3AED;padding-left:10px;}"
                + "p{margin-bottom:12px;color:#374151;}"
                + "ul{padding-left:20px;margin-bottom:12px;}"
                + "li{margin-bottom:6px;color:#374151;}"
                + "b{color:#1E293B;}"
                + "blockquote{background:#F5F3FF;border-left:4px solid #7C3AED;"
                + "margin:16px 0;padding:12px 16px;border-radius:0 12px 12px 0;color:#374151;}"
                + "</style></head><body>"
                + bodyContent
                + "</body></html>";
    }

    private void bindQuiz(LessonResponse lesson) {
        currentQuestionIndex = 0;
        selectedOption = null;
        layoutQuizFeedback.setVisibility(View.GONE);
        tvQuestionText.setText("Đang tải...");
        rvQuizOptions.setAdapter(null);
        btnPrimaryAction.setText("Câu tiếp theo");
        btnPrimaryAction.setEnabled(false);

        learningService.createQuizSession(lesson.getId()).enqueue(new Callback<ApiResponse<QuizSessionResponse>>() {
            @Override
            public void onResponse(Call<ApiResponse<QuizSessionResponse>> call, Response<ApiResponse<QuizSessionResponse>> response) {
                if (response.isSuccessful() && response.body() != null && response.body().getData() != null) {
                    currentQuizSessionId = response.body().getData().getId();
                    loadQuizQuestions();
                } else {
                    ToastUtil.showCustomToast(LessonActivity.this, "Lỗi tạo session quiz");
                }
            }
            @Override
            public void onFailure(Call<ApiResponse<QuizSessionResponse>> call, Throwable t) {
                ToastUtil.showCustomToast(LessonActivity.this, "Lỗi kết nối tạo session");
            }
        });

        updateSheetProgress();
    }

    private void loadQuizQuestions() {
        learningService.getQuizSessionQuestions(currentQuizSessionId, null, 100).enqueue(new Callback<PaginatedApiResponseQuizSessionQuestionResponse>() {
            @Override
            public void onResponse(Call<PaginatedApiResponseQuizSessionQuestionResponse> call, Response<PaginatedApiResponseQuizSessionQuestionResponse> response) {
                // Because QuizSessionQuestionResponse doesn't have the text of options / titles
                // Let's call CourseService to get actual info
                courseService.getQuizByLessonId(currentLessonId).enqueue(new Callback<ApiResponse<com.app.cinx.api.dto.QuizLessonResponse>>() {
                    @Override
                    public void onResponse(Call<ApiResponse<com.app.cinx.api.dto.QuizLessonResponse>> call, Response<ApiResponse<com.app.cinx.api.dto.QuizLessonResponse>> response) {
                        if (response.isSuccessful() && response.body() != null && response.body().getData() != null) {
                            apiQuestions = response.body().getData().getQuestions();
                            if (apiQuestions != null && !apiQuestions.isEmpty()) {
                                showQuestion(0);
                                btnPrimaryAction.setEnabled(true);
                                startQuizTimer(QUIZ_TIME_MILLIS);
                            }
                        }
                    }
                    @Override
                    public void onFailure(Call<ApiResponse<com.app.cinx.api.dto.QuizLessonResponse>> call, Throwable t) {}
                });
            }
            @Override
            public void onFailure(Call<PaginatedApiResponseQuizSessionQuestionResponse> call, Throwable t) {}
        });
    }

    private void showQuestion(int index) {
        if (apiQuestions == null || index >= apiQuestions.size()) return;

        QuizQuestionResponse question = apiQuestions.get(index);

        tvQuestionCounter.setText(String.format(Locale.getDefault(), "CÂU HỎI %d/%d", index + 1, apiQuestions.size()));

        int pct = (int) ((index + 1) / (float) apiQuestions.size() * 100);
        quizProgressBar.setProgress(pct);

        tvQuestionText.setText(question.getQuestionText() != null ? question.getQuestionText() : "");

        selectedOption = null;
        layoutQuizFeedback.setVisibility(View.GONE);

        List<QuizOptionResponse> opts = question.getOptions() != null ? question.getOptions() : new ArrayList<>();
        quizOptionAdapter = new QuizOptionAdapter(this, opts);
        quizOptionAdapter.setOnOptionSelectedListener((pos, option) -> {
            selectedOption = option;
            quizOptionAdapter.selectOption(pos);
            btnPrimaryAction.setText(currentQuestionIndex == apiQuestions.size() - 1 ? "Nộp bài" : "Câu tiếp theo");
        });
        rvQuizOptions.setAdapter(quizOptionAdapter);

        btnPrimaryAction.setText(index == apiQuestions.size() - 1 ? "Nộp bài" : "Câu tiếp theo");
    }

    private void handlePrimaryAction() {
        LessonResponse lesson = lessons.get(currentIndex);
        String t = lesson.getLessonType() != null ? lesson.getLessonType() : "";
        if (t.equalsIgnoreCase("VIDEO") || t.equalsIgnoreCase("DOCUMENT") || t.equalsIgnoreCase("ARTICLE")) {
            completedLessonIds.add(lesson.getId());
            navigateToNextLesson();
        } else if (t.equalsIgnoreCase("QUIZ")) {
            if (selectedOption != null) {
                ChooseQuizAnswerRequest req = new ChooseQuizAnswerRequest();
                req.setQuestionId(apiQuestions.get(currentQuestionIndex).getId());
                req.setUserAnswer(selectedOption.getOptionText());
                learningService.chooseQuizSessionQuestion(currentQuizSessionId, req).enqueue(new Callback<ApiResponse<Object>>() {
                   @Override
                   public void onResponse(Call<ApiResponse<Object>> call, Response<ApiResponse<Object>> response) {}
                   @Override
                   public void onFailure(Call<ApiResponse<Object>> call, Throwable t) {}
                });
            }

            if (currentQuestionIndex < apiQuestions.size() - 1) {
                currentQuestionIndex++;
                showQuestion(currentQuestionIndex);
            } else {
                SubmitQuizSessionRequest submitReq = new SubmitQuizSessionRequest();
                learningService.submitQuizSession(currentQuizSessionId, submitReq).enqueue(new Callback<ApiResponse<QuizSessionResponse>>() {
                    @Override
                    public void onResponse(Call<ApiResponse<QuizSessionResponse>> call, Response<ApiResponse<QuizSessionResponse>> response) {
                        layoutQuizFeedback.setVisibility(View.VISIBLE);
                        layoutQuizFeedback.setBackgroundResource(R.drawable.bg_quiz_option_correct);
                        tvFeedbackTitle.setText("Hoàn thành! Đang chuyển bài...");

                        btnPrimaryAction.setText("Bài tiếp theo");
                        btnPrimaryAction.setOnClickListener(v -> navigateToNextLesson());
                    }
                    @Override
                    public void onFailure(Call<ApiResponse<QuizSessionResponse>> call, Throwable t) {
                        ToastUtil.showCustomToast(LessonActivity.this, "Lỗi nộp bài");
                    }
                });
            }
        }
    }

    private void startQuizTimer(long millisInFuture) {
        cancelQuizTimer();
        quizCountDownTimer = new CountDownTimer(millisInFuture, 1000) {
            @Override public void onTick(long millisUntilFinished) {
                long minutes = millisUntilFinished / 60000;
                long seconds = (millisUntilFinished % 60000) / 1000;
                tvQuizTimer.setText(String.format(Locale.getDefault(), "%02d:%02d", minutes, seconds));
            }
            @Override public void onFinish() {
                tvQuizTimer.setText("00:00");
                handlePrimaryAction(); 
            }
        }.start();
    }

    private void cancelQuizTimer() {
        if (quizCountDownTimer != null) {
            quizCountDownTimer.cancel();
            quizCountDownTimer = null;
        }
    }

    private void setupBottomBar() {
        btnPrevLesson.setOnClickListener(v -> navigateToPrevLesson());
        btnPrimaryAction.setOnClickListener(v -> handlePrimaryAction());
    }

    private void updateBottomBarState(LessonResponse lesson) {
        boolean hasPrev = currentIndex > 0;
        btnPrevLesson.setEnabled(hasPrev);
        btnPrevLesson.setAlpha(hasPrev ? 1f : 0.4f);

        String t = lesson.getLessonType() != null ? lesson.getLessonType() : "";
        if (!t.equalsIgnoreCase("QUIZ")) {
            btnPrimaryAction.setText("Hoàn thành & Tiếp tục");
        }
    }

    private void navigateToPrevLesson() {
        if (currentIndex > 0) loadLesson(currentIndex - 1);
    }

    private void navigateToNextLesson() {
        int next = currentIndex + 1;
        if (next < lessons.size() && !isAllLocked) {
            loadLesson(next);
        } else {
            ToastUtil.showCustomToast(this, "Bạn đã hoàn thành bài học! ");
            finish();
        }
    }

    private void setupBottomSheet() {
        View bottomSheet = findViewById(R.id.bottomSheet);
        sheetBehavior = BottomSheetBehavior.from(bottomSheet);
        sheetBehavior.setState(BottomSheetBehavior.STATE_HIDDEN);
        sheetBehavior.setSkipCollapsed(true);

        sheetBehavior.addBottomSheetCallback(new BottomSheetBehavior.BottomSheetCallback() {
            @Override public void onStateChanged(@androidx.annotation.NonNull View view, int newState) {
                boolean visible = newState != BottomSheetBehavior.STATE_HIDDEN;
                sheetOverlay.setVisibility(visible ? View.VISIBLE : View.GONE);
            }
            @Override public void onSlide(@androidx.annotation.NonNull View view, float offset) {}
        });

        RecyclerView rvCurriculum = findViewById(R.id.rvCurriculum);
        sheetAdapter = new LessonSheetAdapter(this);
        sheetAdapter.setChapters(chapters);
        sheetAdapter.setOnLessonClickListener(lesson -> {
            int idx = findLessonIndex(lesson.getId());
            loadLesson(idx);
            collapseBottomSheet();
        });
        rvCurriculum.setLayoutManager(new LinearLayoutManager(this));
        rvCurriculum.setAdapter(sheetAdapter);

        updateSheetProgress();
    }

    private void refreshSheetAdapter() {
        if (sheetAdapter == null || currentIndex >= lessons.size()) return;
        String activeLessonId = lessons.get(currentIndex).getId();
        sheetAdapter.setActiveLessonId(activeLessonId);
        updateSheetProgress();
    }

    private void updateSheetProgress() {
        int total = lessons.size();
        if (total == 0) return;
        int completed = 0;
        for (LessonResponse l : lessons) if (completedLessonIds.contains(l.getId())) completed++;

        if (tvSheetSubtitle != null) {
            tvSheetSubtitle.setText(total + " bài học • Hoàn thành "
                    + (int)(completed * 100f / total) + "%");
        }
        if (tvSheetProgress != null) {
            tvSheetProgress.setText(completed + "/" + total);
        }
    }

    private void toggleBottomSheet() {
        if (sheetBehavior.getState() == BottomSheetBehavior.STATE_HIDDEN) {
            sheetBehavior.setState(BottomSheetBehavior.STATE_EXPANDED);
        } else {
            collapseBottomSheet();
        }
    }

    private void collapseBottomSheet() {
        sheetBehavior.setState(BottomSheetBehavior.STATE_HIDDEN);
    }
}

package com.app.cinx.activity;

import android.animation.ObjectAnimator;
import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.view.animation.DecelerateInterpolator;
import android.widget.EditText;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;

import androidx.appcompat.app.AppCompatActivity;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.app.cinx.R;
import com.app.cinx.adapter.VoucherProfileAdapter;
import com.app.cinx.model.ProfileVoucher;
import com.app.cinx.utils.ToastUtil;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * VouchersActivity
 *
 * Shows the user's discount vouchers in a ticket-style list.
 * Features:
 *  - Segmented tab: "Khả dụng" / "Hết hạn / Đã dùng"
 *  - Add voucher by code
 *  - Bottom sheet with full voucher detail + copy code
 */
public class VouchersActivity extends AppCompatActivity
        implements VoucherProfileAdapter.VoucherListener {

    // ─────────────────────────────────────────────────────────────────
    // Views
    // ─────────────────────────────────────────────────────────────────

    private ImageView      btnBack;
    private TextView       tabAvailable;
    private TextView       tabExpired;
    private EditText       etVoucherCode;
    private TextView       btnSaveCode;
    private RecyclerView   rvVouchers;
    private LinearLayout   emptyState;

    // Detail bottom sheet views
    private View           sheetOverlay;
    private View           voucherDetailSheet;
    private TextView       tvSheetTitle;
    private TextView       tvSheetCode;
    private TextView       tvSheetExpiry;
    private LinearLayout   llConditions;
    private ImageView      btnCopyCode;
    private TextView       btnUnderstood;

    // ─────────────────────────────────────────────────────────────────
    // Data
    // ─────────────────────────────────────────────────────────────────

    private VoucherProfileAdapter adapter;
    private final List<ProfileVoucher> allVouchers = buildSampleVouchers();
    private boolean showingAvailable = true;

    // ─────────────────────────────────────────────────────────────────
    // Lifecycle
    // ─────────────────────────────────────────────────────────────────

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_vouchers);

        bindViews();
        setupBackButton();
        setupTabs();
        setupAddCode();
        setupSheet();
        loadTab(true);
    }

    // ─────────────────────────────────────────────────────────────────
    // View binding
    // ─────────────────────────────────────────────────────────────────

    private void bindViews() {
        btnBack             = findViewById(R.id.btnBack);
        tabAvailable        = findViewById(R.id.tabAvailable);
        tabExpired          = findViewById(R.id.tabExpired);
        etVoucherCode       = findViewById(R.id.etVoucherCode);
        btnSaveCode         = findViewById(R.id.btnSaveCode);
        rvVouchers          = findViewById(R.id.rvVouchers);
        emptyState          = findViewById(R.id.emptyState);
        sheetOverlay        = findViewById(R.id.sheetOverlay);
        voucherDetailSheet  = findViewById(R.id.voucherDetailSheet);
        tvSheetTitle        = findViewById(R.id.tvSheetTitle);
        tvSheetCode         = findViewById(R.id.tvSheetCode);
        tvSheetExpiry       = findViewById(R.id.tvSheetExpiry);
        llConditions        = findViewById(R.id.llConditions);
        btnCopyCode         = findViewById(R.id.btnCopyCode);
        btnUnderstood       = findViewById(R.id.btnUnderstood);

        // Setup RecyclerView
        adapter = new VoucherProfileAdapter(new ArrayList<>(), this);
        rvVouchers.setLayoutManager(new LinearLayoutManager(this));
        rvVouchers.setAdapter(adapter);
    }

    // ─────────────────────────────────────────────────────────────────
    // Tabs
    // ─────────────────────────────────────────────────────────────────

    private void setupBackButton() {
        btnBack.setOnClickListener(v -> finish());
    }

    private void setupTabs() {
        tabAvailable.setOnClickListener(v -> {
            if (!showingAvailable) {
                showingAvailable = true;
                updateTabStyle();
                loadTab(true);
            }
        });
        tabExpired.setOnClickListener(v -> {
            if (showingAvailable) {
                showingAvailable = false;
                updateTabStyle();
                loadTab(false);
            }
        });
    }

    private void updateTabStyle() {
        if (showingAvailable) {
            tabAvailable.setBackgroundResource(R.drawable.bg_segment_active);
            tabAvailable.setTextColor(getColor(R.color.text_primary));
            tabExpired  .setBackgroundResource(android.R.color.transparent);
            tabExpired  .setTextColor(getColor(R.color.text_secondary));
        } else {
            tabExpired  .setBackgroundResource(R.drawable.bg_segment_active);
            tabExpired  .setTextColor(getColor(R.color.text_primary));
            tabAvailable.setBackgroundResource(android.R.color.transparent);
            tabAvailable.setTextColor(getColor(R.color.text_secondary));
        }
    }

    private void loadTab(boolean available) {
        List<ProfileVoucher> filtered = allVouchers.stream()
                .filter(v -> available
                        ? v.getStatus() == ProfileVoucher.Status.AVAILABLE
                        : v.getStatus() != ProfileVoucher.Status.AVAILABLE)
                .collect(Collectors.toList());

        adapter.setItems(filtered);

        boolean empty = filtered.isEmpty();
        rvVouchers.setVisibility(empty ? View.GONE  : View.VISIBLE);
        emptyState .setVisibility(empty ? View.VISIBLE : View.GONE);

        // Update tab label with count
        if (available) {
            tabAvailable.setText(getString(R.string.voucher_tab_available_count,
                    filtered.size()));
        } else {
            tabExpired.setText(getString(R.string.voucher_tab_expired));
        }
    }

    // ─────────────────────────────────────────────────────────────────
    // Add code
    // ─────────────────────────────────────────────────────────────────

    private void setupAddCode() {
        btnSaveCode.setOnClickListener(v -> {
            String code = etVoucherCode.getText().toString().trim().toUpperCase();
            if (code.isEmpty()) {
                ToastUtil.showCustomToast(this, getString(R.string.voucher_enter_code));
                return;
            }
            // TODO: validate code against backend; for now show feedback
            ToastUtil.showCustomToast(this, getString(R.string.voucher_code_saved, code));
            etVoucherCode.setText("");
        });
    }

    // ─────────────────────────────────────────────────────────────────
    // Bottom sheet
    // ─────────────────────────────────────────────────────────────────

    private void setupSheet() {
        sheetOverlay.setOnClickListener(v -> hideSheet());
        btnUnderstood.setOnClickListener(v -> hideSheet());
        btnCopyCode.setOnClickListener(v -> {
            String code = tvSheetCode.getText().toString();
            android.content.ClipboardManager cm =
                    (android.content.ClipboardManager) getSystemService(CLIPBOARD_SERVICE);
            cm.setPrimaryClip(android.content.ClipData.newPlainText("voucher_code", code));
            ToastUtil.showCustomToast(this, getString(R.string.voucher_code_copied));
        });
    }

    /** Show the detail bottom sheet for a given voucher. */
    private void showSheet(ProfileVoucher voucher) {
        tvSheetTitle.setText(voucher.getTitle());
        tvSheetCode .setText(voucher.getCode());
        tvSheetExpiry.setText(getString(R.string.voucher_detail_expiry_value,
                voucher.getExpiryDate()));

        // Build conditions list
        llConditions.removeAllViews();
        for (String condition : getSampleConditions(voucher)) {
            TextView tv = new TextView(this);
            tv.setText("• " + condition);
            tv.setTextSize(14f);
            tv.setTextColor(getColor(R.color.text_primary));
            int dp6 = (int) (6 * getResources().getDisplayMetrics().density);
            tv.setPadding(0, dp6, 0, 0);
            llConditions.addView(tv);
        }

        // Show overlay + animate sheet up
        sheetOverlay.setVisibility(View.VISIBLE);
        sheetOverlay.setAlpha(0f);
        sheetOverlay.animate().alpha(1f).setDuration(250).start();

        voucherDetailSheet.post(() -> {
            float startY = voucherDetailSheet.getHeight();
            ObjectAnimator anim = ObjectAnimator.ofFloat(
                    voucherDetailSheet, "translationY", startY, 0f);
            anim.setDuration(350);
            anim.setInterpolator(new DecelerateInterpolator());
            anim.start();
        });
    }

    public void hideSheet() {
        float endY = voucherDetailSheet.getHeight();
        ObjectAnimator anim = ObjectAnimator.ofFloat(
                voucherDetailSheet, "translationY", 0f, endY);
        anim.setDuration(300);
        anim.setInterpolator(new DecelerateInterpolator());
        anim.addListener(new android.animation.AnimatorListenerAdapter() {
            @Override
            public void onAnimationEnd(android.animation.Animator animation) {
                sheetOverlay.setVisibility(View.GONE);
            }
        });
        sheetOverlay.animate().alpha(0f).setDuration(250).start();
        anim.start();
    }

    @Override
    public void onBackPressed() {
        if (sheetOverlay.getVisibility() == View.VISIBLE) {
            hideSheet();
        } else {
            super.onBackPressed();
        }
    }

    // ─────────────────────────────────────────────────────────────────
    // VoucherListener callbacks
    // ─────────────────────────────────────────────────────────────────

    @Override
    public void onUseVoucher(ProfileVoucher voucher) {
        // Navigate back with selected voucher code so the caller (Cart/Checkout) can apply it
        Intent result = new Intent();
        result.putExtra("voucher_code", voucher.getCode());
        setResult(RESULT_OK, result);
        finish();
    }

    @Override
    public void onSeeDetail(ProfileVoucher voucher) {
        showSheet(voucher);
    }

    // ─────────────────────────────────────────────────────────────────
    // Sample data helpers
    // ─────────────────────────────────────────────────────────────────

    private List<String> getSampleConditions(ProfileVoucher v) {
        return Arrays.asList(
                "Giảm trực tiếp vào tổng giá trị đơn hàng khóa học.",
                "Mức giảm tối đa không vượt quá giới hạn của từng chương trình.",
                "Mỗi tài khoản chỉ được sử dụng voucher 1 lần duy nhất.",
                "Không áp dụng đồng thời cùng các mã giảm giá khác.",
                "Voucher không có giá trị quy đổi thành tiền mặt dưới mọi hình thức."
        );
    }

    private List<ProfileVoucher> buildSampleVouchers() {
        return Arrays.asList(
                new ProfileVoucher(
                        "v001",
                        "Ưu đãi thành viên mới",
                        "Áp dụng cho mọi khóa học trên hệ thống. Giảm 20% tổng đơn.",
                        "VOUCHER20",
                        ProfileVoucher.DiscountType.PERCENT,
                        20,
                        "30/06/2026",
                        ProfileVoucher.Status.AVAILABLE,
                        1,
                        R.drawable.bg_voucher_left_purple
                ),
                new ProfileVoucher(
                        "v002",
                        "Giảm trực tiếp 100K",
                        "Áp dụng cho danh mục Design & Code. Đơn tối thiểu 500K.",
                        "SAVE100",
                        ProfileVoucher.DiscountType.FIXED,
                        100,
                        "15/07/2026",
                        ProfileVoucher.Status.AVAILABLE,
                        0,
                        R.drawable.bg_voucher_left_teal
                ),
                new ProfileVoucher(
                        "v003",
                        "Flash Sale 30%",
                        "Voucher chương trình Flash Sale tháng 3/2026.",
                        "FLASH30",
                        ProfileVoucher.DiscountType.PERCENT,
                        30,
                        "31/03/2026",
                        ProfileVoucher.Status.EXPIRED,
                        0,
                        R.drawable.bg_voucher_left_gray
                )
        );
    }
}

package com.app.cinx.activity;

import android.animation.ObjectAnimator;
import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.view.animation.DecelerateInterpolator;
import android.widget.EditText;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;

import androidx.appcompat.app.AppCompatActivity;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.app.cinx.R;
import com.app.cinx.adapter.VoucherProfileAdapter;
import com.app.cinx.model.ProfileVoucher;
import com.app.cinx.utils.ToastUtil;

import com.app.cinx.api.EnrollmentService;
import com.app.cinx.api.RetrofitClient;
import com.app.cinx.api.dto.ApiResponse;
import com.app.cinx.api.dto.PaginatedApiResponseVoucherResponse;
import com.app.cinx.api.dto.VoucherResponse;
import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import android.util.Log;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * VouchersActivity
 *
 * Shows the user's discount vouchers in a ticket-style list.
 * Features:
 *  - Segmented tab: "Khả dụng" / "Hết hạn / Đã dùng"
 *  - Add voucher by code
 *  - Bottom sheet with full voucher detail + copy code
 */
public class VouchersActivity extends AppCompatActivity
        implements VoucherProfileAdapter.VoucherListener {

    // ─────────────────────────────────────────────────────────────────
    // Views
    // ─────────────────────────────────────────────────────────────────

    private ImageView      btnBack;
    private TextView       tabAvailable;
    private TextView       tabExpired;
    private EditText       etVoucherCode;
    private TextView       btnSaveCode;
    private RecyclerView   rvVouchers;
    private LinearLayout   emptyState;

    // Detail bottom sheet views
    private View           sheetOverlay;
    private View           voucherDetailSheet;
    private TextView       tvSheetTitle;
    private TextView       tvSheetCode;
    private TextView       tvSheetExpiry;
    private LinearLayout   llConditions;
    private ImageView      btnCopyCode;
    private TextView       btnUnderstood;

    // ─────────────────────────────────────────────────────────────────
    // Data
    // ─────────────────────────────────────────────────────────────────

    private VoucherProfileAdapter adapter;
    private final List<ProfileVoucher> allVouchers = new ArrayList<>();
    private boolean showingAvailable = true;

    // ─────────────────────────────────────────────────────────────────
    // Lifecycle
    // ─────────────────────────────────────────────────────────────────

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_vouchers);

        bindViews();
        setupBackButton();
        setupTabs();
        setupAddCode();
        setupSheet();

        fetchVouchers();
    }

    private void fetchVouchers() {
        EnrollmentService service = RetrofitClient.getInstance().getEnrollmentService();
        if (service == null) return;

        service.getVouchers(null).enqueue(new Callback<PaginatedApiResponseVoucherResponse>() {
            @Override
            public void onResponse(Call<PaginatedApiResponseVoucherResponse> call, Response<PaginatedApiResponseVoucherResponse> response) {
                if (response.isSuccessful() && response.body() != null && response.body().getData() != null) {
                    allVouchers.clear();
                    for (VoucherResponse vr : response.body().getData()) {
                        int discount = vr.getDiscountAmount() != null ? vr.getDiscountAmount().intValue() : 0;
                        ProfileVoucher.Status status = ProfileVoucher.Status.AVAILABLE;
                        // Determine status if possible, default to available
                        // Since there's no status in VoucherResponse, we'll assumeAVAILABLE

                        allVouchers.add(new ProfileVoucher(
                                vr.getId(),
                                vr.getCode(), // using code as title
                                vr.getDescription() != null ? vr.getDescription() : "",
                                vr.getCode(),
                                ProfileVoucher.DiscountType.PERCENT, // Assuming % discount
                                discount,
                                vr.getValidTo() != null ? vr.getValidTo() : "Không giới hạn",
                                status,
                                vr.getQuantity() != null ? vr.getQuantity().intValue() : 1,
                                R.drawable.bg_voucher_left_purple // Default icon
                        ));
                    }
                    runOnUiThread(() -> loadTab(showingAvailable));
                }
            }

            @Override
            public void onFailure(Call<PaginatedApiResponseVoucherResponse> call, Throwable t) {
                Log.e("VouchersActivity", "Failed to fetch vouchers", t);
                ToastUtil.showCustomToast(VouchersActivity.this, "Không thể tải danh sách Voucher");
            }
        });
    }

    // ─────────────────────────────────────────────────────────────────
    // View binding
    // ─────────────────────────────────────────────────────────────────

    private void bindViews() {
        btnBack             = findViewById(R.id.btnBack);
        tabAvailable        = findViewById(R.id.tabAvailable);
        tabExpired          = findViewById(R.id.tabExpired);
        etVoucherCode       = findViewById(R.id.etVoucherCode);
        btnSaveCode         = findViewById(R.id.btnSaveCode);
        rvVouchers          = findViewById(R.id.rvVouchers);
        emptyState          = findViewById(R.id.emptyState);
        sheetOverlay        = findViewById(R.id.sheetOverlay);
        voucherDetailSheet  = findViewById(R.id.voucherDetailSheet);
        tvSheetTitle        = findViewById(R.id.tvSheetTitle);
        tvSheetCode         = findViewById(R.id.tvSheetCode);
        tvSheetExpiry       = findViewById(R.id.tvSheetExpiry);
        llConditions        = findViewById(R.id.llConditions);
        btnCopyCode         = findViewById(R.id.btnCopyCode);
        btnUnderstood       = findViewById(R.id.btnUnderstood);

        // Setup RecyclerView
        adapter = new VoucherProfileAdapter(new ArrayList<>(), this);
        rvVouchers.setLayoutManager(new LinearLayoutManager(this));
        rvVouchers.setAdapter(adapter);
    }

    // ─────────────────────────────────────────────────────────────────
    // Tabs
    // ─────────────────────────────────────────────────────────────────

    private void setupBackButton() {
        btnBack.setOnClickListener(v -> finish());
    }

    private void setupTabs() {
        tabAvailable.setOnClickListener(v -> {
            if (!showingAvailable) {
                showingAvailable = true;
                updateTabStyle();
                loadTab(true);
            }
        });
        tabExpired.setOnClickListener(v -> {
            if (showingAvailable) {
                showingAvailable = false;
                updateTabStyle();
                loadTab(false);
            }
        });
    }

    private void updateTabStyle() {
        if (showingAvailable) {
            tabAvailable.setBackgroundResource(R.drawable.bg_segment_active);
            tabAvailable.setTextColor(getColor(R.color.text_primary));
            tabExpired  .setBackgroundResource(android.R.color.transparent);
            tabExpired  .setTextColor(getColor(R.color.text_secondary));
        } else {
            tabExpired  .setBackgroundResource(R.drawable.bg_segment_active);
            tabExpired  .setTextColor(getColor(R.color.text_primary));
            tabAvailable.setBackgroundResource(android.R.color.transparent);
            tabAvailable.setTextColor(getColor(R.color.text_secondary));
        }
    }

    private void loadTab(boolean available) {
        List<ProfileVoucher> filtered = allVouchers.stream()
                .filter(v -> available
                        ? v.getStatus() == ProfileVoucher.Status.AVAILABLE
                        : v.getStatus() != ProfileVoucher.Status.AVAILABLE)
                .collect(Collectors.toList());

        adapter.setItems(filtered);

        boolean empty = filtered.isEmpty();
        rvVouchers.setVisibility(empty ? View.GONE  : View.VISIBLE);
        emptyState .setVisibility(empty ? View.VISIBLE : View.GONE);

        // Update tab label with count
        if (available) {
            tabAvailable.setText(getString(R.string.voucher_tab_available_count,
                    filtered.size()));
        } else {
            tabExpired.setText(getString(R.string.voucher_tab_expired));
        }
    }

    // ─────────────────────────────────────────────────────────────────
    // Add code
    // ─────────────────────────────────────────────────────────────────

    private void setupAddCode() {
        btnSaveCode.setOnClickListener(v -> {
            String code = etVoucherCode.getText().toString().trim().toUpperCase();
            if (code.isEmpty()) {
                ToastUtil.showCustomToast(this, getString(R.string.voucher_enter_code));
                return;
            }

            EnrollmentService service = RetrofitClient.getInstance().getEnrollmentService();
            if (service != null) {
                service.getVoucherByCode(code).enqueue(new Callback<ApiResponse<VoucherResponse>>() {
                    @Override
                    public void onResponse(Call<ApiResponse<VoucherResponse>> call, Response<ApiResponse<VoucherResponse>> response) {
                        if (response.isSuccessful() && response.body() != null && response.body().getData() != null) {
                            ToastUtil.showCustomToast(VouchersActivity.this, getString(R.string.voucher_code_saved, code));
                            etVoucherCode.setText("");
                            fetchVouchers(); // Reload list
                        } else {
                            ToastUtil.showCustomToast(VouchersActivity.this, "Mã voucher không hợp lệ");
                        }
                    }

                    @Override
                    public void onFailure(Call<ApiResponse<VoucherResponse>> call, Throwable t) {
                        ToastUtil.showCustomToast(VouchersActivity.this, "Lỗi kết nối");
                    }
                });
            }
        });
    }

    // ─────────────────────────────────────────────────────────────────
    // Bottom sheet
    // ─────────────────────────────────────────────────────────────────

    private void setupSheet() {
        sheetOverlay.setOnClickListener(v -> hideSheet());
        btnUnderstood.setOnClickListener(v -> hideSheet());
        btnCopyCode.setOnClickListener(v -> {
            String code = tvSheetCode.getText().toString();
            android.content.ClipboardManager cm =
                    (android.content.ClipboardManager) getSystemService(CLIPBOARD_SERVICE);
            cm.setPrimaryClip(android.content.ClipData.newPlainText("voucher_code", code));
            ToastUtil.showCustomToast(this, getString(R.string.voucher_code_copied));
        });
    }

    /** Show the detail bottom sheet for a given voucher. */
    private void showSheet(ProfileVoucher voucher) {
        tvSheetTitle.setText(voucher.getTitle());
        tvSheetCode .setText(voucher.getCode());
        tvSheetExpiry.setText(getString(R.string.voucher_detail_expiry_value,
                voucher.getExpiryDate()));

        // Build conditions list
        llConditions.removeAllViews();
        for (String condition : getSampleConditions(voucher)) {
            TextView tv = new TextView(this);
            tv.setText("• " + condition);
            tv.setTextSize(14f);
            tv.setTextColor(getColor(R.color.text_primary));
            int dp6 = (int) (6 * getResources().getDisplayMetrics().density);
            tv.setPadding(0, dp6, 0, 0);
            llConditions.addView(tv);
        }

        // Show overlay + animate sheet up
        sheetOverlay.setVisibility(View.VISIBLE);
        sheetOverlay.setAlpha(0f);
        sheetOverlay.animate().alpha(1f).setDuration(250).start();

        voucherDetailSheet.post(() -> {
            float startY = voucherDetailSheet.getHeight();
            ObjectAnimator anim = ObjectAnimator.ofFloat(
                    voucherDetailSheet, "translationY", startY, 0f);
            anim.setDuration(350);
            anim.setInterpolator(new DecelerateInterpolator());
            anim.start();
        });
    }

    public void hideSheet() {
        float endY = voucherDetailSheet.getHeight();
        ObjectAnimator anim = ObjectAnimator.ofFloat(
                voucherDetailSheet, "translationY", 0f, endY);
        anim.setDuration(300);
        anim.setInterpolator(new DecelerateInterpolator());
        anim.addListener(new android.animation.AnimatorListenerAdapter() {
            @Override
            public void onAnimationEnd(android.animation.Animator animation) {
                sheetOverlay.setVisibility(View.GONE);
            }
        });
        sheetOverlay.animate().alpha(0f).setDuration(250).start();
        anim.start();
    }

    @Override
    public void onBackPressed() {
        if (sheetOverlay.getVisibility() == View.VISIBLE) {
            hideSheet();
        } else {
            super.onBackPressed();
        }
    }

    // ─────────────────────────────────────────────────────────────────
    // VoucherListener callbacks
    // ─────────────────────────────────────────────────────────────────

    @Override
    public void onUseVoucher(ProfileVoucher voucher) {
        // Navigate back with selected voucher code so the caller (Cart/Checkout) can apply it
        Intent result = new Intent();
        result.putExtra("voucher_code", voucher.getCode());
        setResult(RESULT_OK, result);
        finish();
    }

    @Override
    public void onSeeDetail(ProfileVoucher voucher) {
        showSheet(voucher);
    }

    // ─────────────────────────────────────────────────────────────────
    // Sample data helpers
    // ─────────────────────────────────────────────────────────────────

    private List<String> getSampleConditions(ProfileVoucher v) {
        return Arrays.asList(
                "Giảm trực tiếp vào tổng giá trị đơn hàng khóa học.",
                "Mức giảm tối đa không vượt quá giới hạn của từng chương trình.",
                "Mỗi tài khoản chỉ được sử dụng voucher 1 lần duy nhất.",
                "Không áp dụng đồng thời cùng các mã giảm giá khác.",
                "Voucher không có giá trị quy đổi thành tiền mặt dưới mọi hình thức."
        );
    }

    private List<ProfileVoucher> buildSampleVouchers() {
        return Arrays.asList(
                new ProfileVoucher(
                        "v001",
                        "Ưu đãi thành viên mới",
                        "Áp dụng cho mọi khóa học trên hệ thống. Giảm 20% tổng đơn.",
                        "VOUCHER20",
                        ProfileVoucher.DiscountType.PERCENT,
                        20,
                        "30/06/2026",
                        ProfileVoucher.Status.AVAILABLE,
                        1,
                        R.drawable.bg_voucher_left_purple
                ),
                new ProfileVoucher(
                        "v002",
                        "Giảm trực tiếp 100K",
                        "Áp dụng cho danh mục Design & Code. Đơn tối thiểu 500K.",
                        "SAVE100",
                        ProfileVoucher.DiscountType.FIXED,
                        100,
                        "15/07/2026",
                        ProfileVoucher.Status.AVAILABLE,
                        0,
                        R.drawable.bg_voucher_left_teal
                ),
                new ProfileVoucher(
                        "v003",
                        "Flash Sale 30%",
                        "Voucher chương trình Flash Sale tháng 3/2026.",
                        "FLASH30",
                        ProfileVoucher.DiscountType.PERCENT,
                        30,
                        "31/03/2026",
                        ProfileVoucher.Status.EXPIRED,
                        0,
                        R.drawable.bg_voucher_left_gray
                )
        );
    }
}

package com.app.cinx.activity;

import android.content.Intent;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.widget.ImageButton;
import android.widget.TextView;

import androidx.appcompat.app.AppCompatActivity;
import androidx.appcompat.widget.AppCompatButton;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.app.cinx.R;
import com.app.cinx.adapter.CheckoutCourseAdapter;
import com.app.cinx.adapter.PaymentMethodAdapter;
import com.app.cinx.data.CartRepository;
import com.app.cinx.api.dto.CartItemResponse;
import com.app.cinx.model.PaymentMethod;
import com.app.cinx.utils.Convert;
import com.app.cinx.utils.UserManager;

import com.app.cinx.api.OrderService;
import com.app.cinx.api.RetrofitClient;
import com.app.cinx.api.dto.ApiResponse;
import com.app.cinx.api.dto.CreateOrderRequest;
import com.app.cinx.api.dto.CartItemDto;
import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import android.util.Log;
import com.app.cinx.utils.TokenManager;
import android.widget.Toast;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;


import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;

/**
 * Checkout / Thanh-toán screen.
 *
 * Displays:
 *  1. Receiver information block
 *  2. Compact order-item list (read-only)
 *  3. Payment method selector (MoMo / VNPAY-QR / Thẻ Visa·Mastercard)
 *  4. Order-summary totals (subtotal + voucher discount)
 *
 * On "Đặt hàng":
 *  - Button shows a loading indicator for 1.5 s
 *  - Activity fades out and {@link PaymentSuccessActivity} is launched
 *
 * Architecture notes:
 *  - Cart items are read from {@link CartRepository} (singleton).
 *  - Applied-voucher info travels via Intent extras from CartActivity.
 *  - Payment logic is a stub; swap with real network calls later.
 */
public class CheckoutActivity extends AppCompatActivity {

    // ── Intent keys ──────────────────────────────────────────────────────
    public static final String EXTRA_VOUCHER_PERCENT = "extra_voucher_percent";
    public static final String EXTRA_VOUCHER_TITLE   = "extra_voucher_title";

    // ── Views ─────────────────────────────────────────────────────────────
    private TextView       tvOrderSectionTitle;
    private TextView       tvDetailSubtotalLabel;
    private TextView       tvDetailSubtotalValue;
    private TextView       tvDetailDiscountValue;
    private android.view.View layoutDetailDiscountRow;
    private TextView       tvCheckoutTotal;
    private AppCompatButton btnPlaceOrder;

    // ── Data ──────────────────────────────────────────────────────────────
    private List<CartItemResponse> checkoutItems;  // items carried from cart

    /** Voucher applied in CartActivity (may be null). */
    private int    voucherPercent = 0;
    private String voucherTitle   = null;

    private PaymentMethodAdapter paymentAdapter;
    private boolean              isProcessing = false;

    // ─────────────────────────────────────────────────────────────────────
    // Lifecycle
    // ─────────────────────────────────────────────────────────────────────

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_checkout);

        readExtras();
        collectCheckoutItems();
        bindViews();
        setupRecyclerViews();
        refreshSummary();
        setupClickListeners();
    }

    // ─────────────────────────────────────────────────────────────────────
    // Initialisation helpers
    // ─────────────────────────────────────────────────────────────────────

    private void readExtras() {
        Intent intent = getIntent();
        voucherPercent = intent.getIntExtra(EXTRA_VOUCHER_PERCENT, 0);
        voucherTitle   = intent.getStringExtra(EXTRA_VOUCHER_TITLE);
    }

    /**
     * Grab only the *selected* items from the cart repository.
     * Falls back to all items if none are explicitly selected (e.g. direct launch).
     */
    private void collectCheckoutItems() {
        checkoutItems = new ArrayList<>();
        List<CartItemResponse> all = CartRepository.getInstance().getItems();
        for (CartItemResponse item : all) {
            if (item.isSelected()) checkoutItems.add(item);
        }
        if (checkoutItems.isEmpty()) {
            // Fallback: take everything in the cart
            checkoutItems.addAll(all);
        }
    }

    private void bindViews() {
        ImageButton btnBack = findViewById(R.id.btnCheckoutBack);
        btnBack.setOnClickListener(v -> finish());

        tvOrderSectionTitle      = findViewById(R.id.tvOrderSectionTitle);
        tvDetailSubtotalLabel    = findViewById(R.id.tvDetailSubtotalLabel);
        tvDetailSubtotalValue    = findViewById(R.id.tvDetailSubtotalValue);
        layoutDetailDiscountRow  = findViewById(R.id.layoutDetailDiscountRow);
        tvDetailDiscountValue    = findViewById(R.id.tvDetailDiscountValue);
        tvCheckoutTotal          = findViewById(R.id.tvCheckoutTotal);
        btnPlaceOrder            = findViewById(R.id.btnPlaceOrder);

        // Receiver info — in a real app, pull from UserManager / profile API
        populateUserInfo();
    }

    private void populateUserInfo() {
        TextView tvName  = findViewById(R.id.tvReceiverName);
        TextView tvPhone = findViewById(R.id.tvReceiverPhone);
        TextView tvEmail = findViewById(R.id.tvReceiverEmail);

        UserManager user = UserManager.getInstance();
        if (user.isLoggedIn() && user.getUserEmail() != null) {
            tvEmail.setText("Email: " + user.getUserEmail());
        }
        // Name & phone are kept as sample values until a Profile model is added
    }

    // ─────────────────────────────────────────────────────────────────────
    // RecyclerViews
    // ─────────────────────────────────────────────────────────────────────

    private void setupRecyclerViews() {
        // Order items
        RecyclerView rvItems = findViewById(R.id.rvCheckoutItems);
        rvItems.setLayoutManager(new LinearLayoutManager(this));
        rvItems.setAdapter(new CheckoutCourseAdapter(checkoutItems));
        rvItems.setNestedScrollingEnabled(false);

        // Payment methods
        List<PaymentMethod> paymentMethods = buildPaymentMethods();
        paymentAdapter = new PaymentMethodAdapter(paymentMethods,
                method -> { /* selection handled inside adapter */ });

        RecyclerView rvPayment = findViewById(R.id.rvPaymentMethods);
        rvPayment.setLayoutManager(new LinearLayoutManager(this));
        rvPayment.setAdapter(paymentAdapter);
        rvPayment.setNestedScrollingEnabled(false);
    }

    /** Returns the static list of supported payment methods. */
    private List<PaymentMethod> buildPaymentMethods() {
        return Arrays.asList(
                new PaymentMethod(
                        PaymentMethod.Type.MOMO,
                        getString(R.string.pm_momo_name),
                        getString(R.string.pm_momo_desc),
                        R.drawable.ic_pm_momo,
                        R.drawable.bg_pm_momo),

                new PaymentMethod(
                        PaymentMethod.Type.VNPAY,
                        getString(R.string.pm_vnpay_name),
                        getString(R.string.pm_vnpay_desc),
                        R.drawable.ic_pm_vnpay,
                        R.drawable.bg_pm_vnpay),

                new PaymentMethod(
                        PaymentMethod.Type.CARD,
                        getString(R.string.pm_card_name),
                        getString(R.string.pm_card_desc),
                        R.drawable.ic_pm_card,
                        R.drawable.bg_pm_card)
        );
    }

    // ─────────────────────────────────────────────────────────────────────
    // Price summary  — single source of truth
    // ─────────────────────────────────────────────────────────────────────

    private long calcSubtotal() {
        long sum = 0;
        for (CartItemResponse item : checkoutItems) sum += item.getSalePrice();
        return sum;
    }

    private long calcTotal() {
        long subtotal = calcSubtotal();
        if (voucherPercent <= 0) return subtotal;
        return subtotal - (subtotal * voucherPercent / 100);
    }

    private void refreshSummary() {
        int  count    = checkoutItems.size();
        long subtotal = calcSubtotal();
        long total    = calcTotal();
        long discount = subtotal - total;

        // Section title
        tvOrderSectionTitle.setText(getString(R.string.checkout_order_section, count));

        // Detail block
        tvDetailSubtotalLabel.setText(getString(R.string.checkout_subtotal, count));
        tvDetailSubtotalValue.setText(Convert.formatVnd(subtotal));

        if (voucherPercent > 0 && discount > 0) {
            layoutDetailDiscountRow.setVisibility(android.view.View.VISIBLE);
            tvDetailDiscountValue.setText("−" + Convert.formatVnd(discount));
        } else {
            layoutDetailDiscountRow.setVisibility(android.view.View.GONE);
        }

        // Bottom bar total
        tvCheckoutTotal.setText(Convert.formatVnd(total));
    }

    // ─────────────────────────────────────────────────────────────────────
    // Click listeners
    // ─────────────────────────────────────────────────────────────────────

    private void setupClickListeners() {
        btnPlaceOrder.setOnClickListener(v -> {
            if (!isProcessing) startOrderProcessing();
        });
    }

    /**
     * Simulates a payment-processing round trip:
     *  1. Disable the button and show a "loading" label.
     *  2. After 1.5 s, launch {@link PaymentSuccessActivity} with order details.
     *  3. Fade out this screen to match the screenshot transition.
     */
    private void startOrderProcessing() {
        if (checkoutItems.isEmpty()) return;

        isProcessing = true;
        btnPlaceOrder.setText(getString(R.string.checkout_processing));
        btnPlaceOrder.setEnabled(false);

        // Dim the whole screen to give it a "processing" look
        android.view.View rootView = findViewById(android.R.id.content);
        rootView.animate()
                .alpha(0.6f)
                .setDuration(400)
                .start();

        OrderService orderService = RetrofitClient.getInstance().getOrderService();
        if (orderService == null) {
            new Handler(Looper.getMainLooper()).postDelayed(this::launchSuccessScreen, 1500);
            return;
        }

        CreateOrderRequest request = new CreateOrderRequest();
        List<CartItemDto> cartItemDtos = new ArrayList<>();
        for (CartItemResponse ci : checkoutItems) {
            CartItemDto dto = new CartItemDto();
            dto.setId(ci.getId());
            cartItemDtos.add(dto);
        }
        request.setCartItems(cartItemDtos);

        PaymentMethod pm = paymentAdapter.getSelectedMethod();
        request.setPaymentMethod(pm != null ? pm.getName() : "CARD");

        if (voucherTitle != null) {
            request.setVoucherCode(voucherTitle);
        }
        orderService.createOrder(token, request).enqueue(new Callback<ApiResponse<Void>>() {
            @Override
            public void onResponse(Call<ApiResponse<Void>> call, Response<ApiResponse<Void>> response) {
                if (response.isSuccessful()) {
                    launchSuccessScreen();
                } else {
                    handleError();
                }
            }

            @Override
            public void onFailure(Call<ApiResponse<Void>> call, Throwable t) {
                Log.e("Checkout", "Failed to place order", t);
                handleError();
            }
        });
    }

    private void handleError() {
        isProcessing = false;
        btnPlaceOrder.setText("Thử lại");
        btnPlaceOrder.setEnabled(true);
        android.view.View rootView = findViewById(android.R.id.content);
        rootView.animate().alpha(1.0f).setDuration(400).start();
        Toast.makeText(this, "Order failed, please try again", Toast.LENGTH_SHORT).show();
    }

    private void launchSuccessScreen() {
        // Generate a simple mock order code
        String orderCode = "EDUF-" + Integer.toHexString((int) (System.currentTimeMillis() % 0xFFFFF))
                .toUpperCase();

        UserManager user = UserManager.getInstance();
        String email = (user.isLoggedIn() && user.getUserEmail() != null)
                ? user.getUserEmail()
                : "khoa.vu@example.com";

        Intent intent = new Intent(this, PaymentSuccessActivity.class);
        intent.putExtra(PaymentSuccessActivity.EXTRA_ORDER_CODE, orderCode);
        intent.putExtra(PaymentSuccessActivity.EXTRA_EMAIL, email);
        intent.putExtra(PaymentSuccessActivity.EXTRA_AMOUNT, Convert.formatVnd(calcTotal()));
        startActivity(intent);

        // Custom transition: fade out cart → success
        overridePendingTransition(android.R.anim.fade_in, android.R.anim.fade_out);

        // Clear the back stack up to (but not including) MainActivity
        CartRepository.getInstance().clear();
        finish();
    }
}

